    assign readback_array[9][26:25] = (decoded_reg_strb.CMD_CTL && !decoded_req_is_wr) ? field_storage.CMD_CTL.acc_ctrl.value : '0;
    assign readback_array[9][31:27] = '0;
    assign readback_array[10][31:0] = (decoded_reg_strb.RES_LINE && !decoded_req_is_wr) ? hwif_in.RES_LINE.value.next : '0;
    assign readback_array[11][31:0] = (decoded_reg_strb.RES_FLAGS && !decoded_req_is_wr) ? hwif_in.RES_FLAGS.value.next : '0;
    assign readback_array[12][15:0] = (decoded_reg_strb.RES_TIME && !decoded_req_is_wr) ? hwif_in.RES_TIME.issue.next : '0;
    assign readback_array[12][31:16] = (decoded_reg_strb.RES_TIME && !decoded_req_is_wr) ? hwif_in.RES_TIME.retire.next : '0;
    assign readback_array[13][0:0] = (decoded_reg_strb.RES_STATUS && !decoded_req_is_wr) ? hwif_in.RES_STATUS.err.next : '0;
    assign readback_array[13][31:1] = '0;
    assign readback_array[14][0:0] = (decoded_reg_strb.STATUS && !decoded_req_is_wr) ? hwif_in.STATUS.busy.next : '0;
    assign readback_array[14][1:1] = (decoded_reg_strb.STATUS && !decoded_req_is_wr) ? hwif_in.STATUS.done.next : '0;
    assign readback_array[14][15:2] = '0;
    assign readback_array[14][31:16] = (decoded_reg_strb.STATUS && !decoded_req_is_wr) ? hwif_in.STATUS.issued.next : '0;
    assign readback_array[15][31:0] = (decoded_reg_strb.RETIRED && !decoded_req_is_wr) ? hwif_in.RETIRED.value.next : '0;
    assign readback_array[16][31:0] = (decoded_reg_strb.CYCLES && !decoded_req_is_wr) ? hwif_in.CYCLES.value.next : '0;
    assign readback_array[17][31:0] = (decoded_reg_strb.STALL_CYCLES && !decoded_req_is_wr) ? hwif_in.STALL_CYCLES.value.next : '0;
    assign readback_array[18][31:0] = (decoded_reg_strb.ERR_COUNT && !decoded_req_is_wr) ? hwif_in.ERR_COUNT.value.next : '0;

    // Reduce the array
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
        readback_data_var = '0;
        for(int i=0; i<19; i++) readback_data_var |= readback_array[i];
        readback_data = readback_data_var;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
